{
  "findings": [
    {
      "check_id": "CKV_AZURE_88",
      "title": "Azure Function App uses plain text storage account access key",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "HIGH",
      "explanation": "The storage_account_access_key is stored in plain text within the Terraform state, posing a risk of exposure."
    }
  ],
  "patched_code": "resource \"azurerm_function_app\" \"changeme_simple_function_app\" {\n  name                       = \"changeme-simple-function-app-name\"\n  location                   = azurerm_resource_group.changeme_simple_function_app_resource_group.location\n  resource_group_name        = azurerm_resource_group.changeme_simple_function_app_resource_group.name\n  app_service_plan_id        = azurerm_app_service_plan.changeme_simple_function_app_app_service_plan.id\n  storage_account_name       = azurerm_storage_account.changeme_simple_function_app_storage_account.name\n  storage_account_access_key = azurerm_storage_account.changeme_simple_function_app_storage_account.primary_access_key\n  identity {\n    type = \"SystemAssigned\"\n  }\n}",
  "fix_summary": "Enabled system-assigned managed identity for the Azure Function App to avoid using plain text storage account access key."
}
